// The automation watches a single fiscal host: Open Source Europe,
// whose host slug on Open Collective is 'europe'.
return [
  { json: { host_slug: 'europe', org: 'OSE' } },
];

// Flattens the per-host GraphQL responses into one item per pending
// application, shaped exactly like an ose_applications row.
const ORG_BY_HOST = { 'europe': 'OSE' };
const out = [];
for (const item of $input.all()) {
  const host = item.json.data && item.json.data.host;
  if (!host) {
    throw new Error('intake: unexpected GraphQL response: ' + JSON.stringify(item.json.errors || item.json).slice(0, 500));
  }
  for (const node of host.hostApplications.nodes) {
    const account = node.account || {};
    if (!account.slug) continue;
    const links = account.socialLinks || [];
    const repoLink = links.find((l) => ['GITHUB', 'GITLAB', 'GIT_REPOSITORY'].includes(l.type));
    const siteLink = links.find((l) => l.type === 'WEBSITE');
    const adminEmails = ((account.members || {}).nodes || [])
      .map((m) => (m.account || {}).email)
      .filter(Boolean);
    const custom = node.customData || {};
    out.push({ json: {
      slug: account.slug,
      org: ORG_BY_HOST[host.slug] || host.slug,
      host_slug: host.slug,
      collective_name: account.name || account.slug,
      collective_url: 'https://opencollective.com/' + account.slug,
      description: account.description || '',
      long_description: account.longDescription || '',
      repository_url: (repoLink || {}).url || '',
      website_url: (siteLink || {}).url || '',
      application_message: node.message || '',
      applicant_email: custom.email || custom.contactEmail || adminEmails[0] || '',
      applied_at: node.createdAt,
    }});
  }
}
return out;

// Pairs each status response with its state row (the HTTP node emits one
// response per input row, in order) and keeps only rows whose application
// reached a terminal state on Open Collective.
//
// This read account.hostApplicationRequests until 2026-10-01. That field demands
// admin of the applicant collective, which a host-admin token is not and cannot
// become, so every response came back Unauthorized with a null account, the
// `if (!account) return` below swallowed it, and the node reported success while
// recording nothing. Seven decisions were missed that way. These public fields
// carry the same answer:
//
//   host.slug === host_slug, isApproved false -> still pending, leave it
//   host.slug === host_slug, isApproved true  -> approved
//   host === null                             -> applying nowhere now: rejected
//   host.slug is a different host             -> gone elsewhere: resigned
//
// That last case is real here, not theoretical: an applicant can apply to OSE and
// to the sibling host, and one did. It can end in neither an approval nor a
// rejection from us, because the collective is no longer ours to decide on, so it
// gets a terminal outcome of its own. That outcome sends no email: the branch stops
// at the data table and the Slack thread, which is what makes a wrong call cost one
// hand edit rather than a message to an applicant. `other_host` carries the host
// that was found, so the thread can name it and a reviewer can judge.
const rows = $('Still open?').all();
const out = [];
$input.all().forEach((item, i) => {
  const row = rows[i].json;
  const body = item.json || {};
  if (Array.isArray(body.errors) && body.errors.length) {
    // Shout, never swallow: a silent skip here is what hid the original breakage.
    throw new Error(`decision: Open Collective refused the status query for ${row.slug}: ${JSON.stringify(body.errors)}`);
  }
  const account = body.data && body.data.account;
  if (!account) return; // collective gone or renamed — leave the row for a human
  if (!('host' in account)) return; // not a host-bearing account type — leave it
  const host = account.host ? account.host.slug : null;
  let decision = '';
  let otherHost = '';
  if (host === row.host_slug) {
    if (account.isApproved !== true) return; // still pending
    decision = 'approved';
  } else if (host === null) {
    decision = 'rejected';
  } else {
    decision = 'resigned';
    otherHost = host;
  }
  out.push({ json: {
    slug: row.slug,
    org: row.org,
    collective_name: row.collective_name,
    applicant_email: row.contact_email || row.applicant_email || '',
    decision,
    other_host: otherHost,
    form_submitted_at: row.form_submitted_at || '',
  }, pairedItem: { item: i } });
});
return out;

const TEMPLATES = {
  approved: `Subject: {{ collective_name }} is approved on Open Collective

Hi,

Welcome on board! We have approved your application to {{ org_name }}.

You can find our hosting documentation here:
https://docs.opencollective.com/open-source-europe

We would also be happy to schedule a short onboarding call to get to know each other a
little better and go through some practical details together. If that would be useful,
please feel free to select a time here:
https://calendly.com/ivan-oce/onboarding-call

Best regards,
The OSE Team`,
  rejected: `Subject: {{ collective_name }} — outcome of your application to {{ org_name }}

Hi,

Thank you for your application to be fiscally hosted by {{ org_name }}, and for taking the
time to share your project with us.

After careful review, we have decided not to move forward with your application. Based on
the information provided, we do not think the project is the right fit for OSE's hosting
framework at this stage.

We appreciate your interest and wish you all the best with the development of your
initiative.

Best regards,
The OSE Team`,
  rejected_no_response: `Subject: {{ collective_name }} — outcome of your application to {{ org_name }}

Hi,

Thank you for your application to be fiscally hosted by {{ org_name }}.

We followed up a few weeks ago with some additional questions, but have not received a
response. Since we need this information in order to continue reviewing your application,
we will close your application for now.

You are welcome to get back in touch at any time if you would like to resume the process.

We wish you all the best with your project.

Best regards,
The OSE Team`
};
const ORG_NAMES = { OSE: 'Open Source Europe' };
const row = $json;
if (!row.applicant_email) throw new Error(`decision email: no address for ${row.slug}`);
// Open Collective reports both kinds of rejection the same way. A rejection before the
// final form page was ever submitted is an application that went silent after the
// invitation and the reminder, so it gets the no-response email rather than the
// not-a-fit one.
const template = row.decision === 'rejected' && !row.form_submitted_at
  ? 'rejected_no_response'
  : row.decision;
const raw = TEMPLATES[template];
if (!raw) throw new Error(`decision email: unknown decision "${row.decision}" for ${row.slug}`);
const vars = { collective_name: row.collective_name, org_name: ORG_NAMES[row.org] || row.org };
const render = (tpl) => tpl.replace(/\{\{\s*(\w+)\s*\}\}/g, (m, key) => {
  const value = vars[key];
  if (value === undefined || value === null || value === '') {
    throw new Error(`decision email: missing "${key}" for ${row.slug}`);
  }
  return String(value);
});
const cut = raw.indexOf('\n');
let subject = render(raw.slice('Subject: '.length, cut));
const body = render(raw.slice(cut).trimStart());
// DRY_RUN fails safe: only the exact string `false` releases mail to the applicant. Unset,
// empty, `1`, `yes` or a trailing space all suppress, so a dropped or mistyped line in .env
// cannot quietly start mailing real people. Going live is the deliberate act of writing
// DRY_RUN=false.
const suppressed = String($env.DRY_RUN || '').trim().toLowerCase() !== 'false';
if (suppressed) subject = `[DRY_RUN → would have gone to ${row.applicant_email}] ${subject}`;
const to = suppressed ? ($env.DRY_RUN_RECIPIENT || '') : row.applicant_email;
if (!to) throw new Error('decision email: DRY_RUN is not "false", so the email is suppressed, but DRY_RUN_RECIPIENT is empty');
return { json: { slug: row.slug, to, subject, body, suppressed } };

// One Slack message per new application. Its timestamp becomes the thread anchor every
// later stage replies to, so it is stored on the row in the next node.
//
// The name, URL and description come from the collective's public Open Collective page,
// which the applicant writes. They are data, not markup: <!channel> in a name, or a masked
// link like <https://evil.example|opencollective.com/theirs> in a description, would
// otherwise be honoured by Slack in the reviewers' channel. Escape the three characters
// Slack treats as control characters, & first so the other two are not escaped twice. Only
// those values go through escapeSlack: the fixed wording keeps its :incoming_envelope: and
// its *bold*, and org resolves from our own host list.
const ORG_NAMES = { OSE: 'Open Source Europe' };

const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const channel = $env.SLACK_CHANNEL || '';
if (!channel) throw new Error('application parent message: SLACK_CHANNEL is empty');
return $input.all().map((item) => {
  const row = item.json;
  const org = ORG_NAMES[row.org] || row.org;
  const text = [
    `:incoming_envelope: *${escapeSlack(row.collective_name)}* applied to ${org}`,
    row.collective_url ? escapeSlack(row.collective_url) : null,
    row.description ? `> ${escapeSlack(row.description)}` : null,
  ].filter(Boolean).join('\n');
  return { json: { slug: row.slug, channel, text } };
});

// The message an applicant writes when they apply on Open Collective. It has been on the
// row since intake and until now nothing but the review prompt read it, so a reviewer
// opening the thread saw the collective's one-line public description and never the
// paragraphs the applicant actually wrote about their project.
//
// It sits between Store Slack thread identifiers and Ask apply 2 to review now so the
// applicant's own words are in the thread before the AI review replies under them. That
// hand-off node runs once with all items, so splitting one application across several
// messages here does not call apply 2 several times. It also means this node must always
// emit at least one item per application, or a quiet application would never be handed
// off and would wait for the next sweep. An empty message therefore still gets a reply
// saying so, which a reviewer wants to read anyway: it says the thread is complete.
//
// The message is the applicant's text, so it is data and not markup: <!channel> in it, or
// a masked link like <https://evil.example|opencollective.com/theirs>, would otherwise be
// honoured by Slack in the reviewers' channel. Escape the three characters Slack treats as
// control characters, & first so the other two are not escaped twice. Only the applicant's
// values go through escapeSlack: the fixed wording keeps its :speech_balloon: and its
// *bold*.
//
// Nothing is ever shortened. Slack truncates a message past 40,000 characters and advises
// staying under 4,000, so the message is packed into replies within BUDGET and continued
// in further replies on the same thread. This is the packer from Render submission thread
// reply in apply 4, with one difference: the applicant's own line breaks are kept, because
// this is prose with paragraphs and a list of links rather than that node's one bullet per
// answer. A blank line is a paragraph the applicant wrote, so the packer's emptiness test
// is on null rather than on falsy, or the blank line would end the message instead of
// joining it.
const BUDGET = 3900;

const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// A cut must never land inside an escaped entity, or &amp; reaches the channel as &am
// followed by p;. When the ampersand nearest the cut has no semicolon before it, the
// entity straddles the cut, so cut at the ampersand instead.
const safeCut = (text, at) => {
  const amp = text.lastIndexOf('&', at - 1);
  if (amp === -1) return at;
  const semi = text.indexOf(';', amp);
  return semi === -1 || semi >= at ? amp : at;
};

// One line can exceed the budget on its own when an applicant writes a paragraph with no
// line break in it. Break it on a space where there is one.
const breakLine = (line) => {
  const pieces = [];
  let rest = String(line);
  while (rest.length > BUDGET) {
    const space = rest.lastIndexOf(' ', BUDGET);
    const at = Math.max(1, safeCut(rest, space > 0 ? space : BUDGET));
    pieces.push(rest.slice(0, at).trimEnd());
    rest = rest.slice(at).trimStart();
  }
  if (rest) pieces.push(rest);
  // A blank line is a paragraph break the applicant wrote and has to survive as an empty
  // piece. Built as a variable and returned on its own line rather than returned as an
  // array literal: validate_workflow reads a returned array literal anywhere in a Code
  // node as the node's own output, helper function or not, and fails it for not being
  // items with a json property.
  const blank = [''];
  return pieces.length ? pieces : blank;
};

// Packs the lines into as few messages as the budget allows, never breaking a line that
// fits in a message of its own.
const pack = (lines) => {
  const messages = [];
  let current = null;
  for (const line of lines) {
    for (const piece of breakLine(line)) {
      if (current === null) {
        current = piece;
      } else if (current.length + 1 + piece.length <= BUDGET) {
        current = `${current}\n${piece}`;
      } else {
        messages.push(current);
        current = piece;
      }
    }
  }
  if (current !== null) messages.push(current);
  // Trimming the ends of a message drops no content: a cut only ever lands on whitespace
  // the packer itself introduced, or on a blank line the applicant left between
  // paragraphs that happens to fall where one message ends and the next begins.
  return messages.map((text) => text.trim()).filter(Boolean);
};

// The name and the message come from Extract new applications rather than from the input,
// which carries only what Post application parent message to Slack returned. That node is
// on every path that reaches this one.
const applications = {};
for (const item of $('Extract new applications').all()) {
  applications[item.json.slug] = item.json;
}

const out = [];
for (const item of $('Skip applications whose Slack post failed').all()) {
  const posted = item.json;
  // Guaranteed by that node, which drops every item whose parent post failed. Checked
  // again because a reply with no anchor lands loose in the channel rather than under the
  // application it belongs to.
  if (!posted.thread_ts || !posted.channel) continue;

  const application = applications[posted.slug] || {};
  const message = String(application.application_message || '')
    .replace(/\r\n?/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();

  const lines = [
    `:speech_balloon: *${escapeSlack(application.collective_name || posted.slug)}* wrote this with their application on Open Collective.`,
    '',
    ...(message
      ? message.split('\n').map((line) => escapeSlack(line))
      : ['_They left the application message empty._']),
  ];

  // Every message carries the same anchor, so the continuations land under the parent in
  // order. Only the first is the reply a reviewer reads first.
  const messages = pack(lines);
  messages.forEach((text, index) => {
    out.push({ json: {
      slug: posted.slug,
      channel: posted.channel,
      thread_ts: posted.thread_ts,
      text: index === 0 ? text : `_continued, ${index + 1} of ${messages.length}_\n${text}`,
    } });
  });
}
return out;

// Rows whose parent message never got posted are skipped rather than posted loose in the
// channel: a reply with no thread_ts lands in the channel with no context.
const LABELS = { approved: ':white_check_mark: Approved on Open Collective',
                 rejected: ':x: Rejected on Open Collective' };

// Both known decisions are fixed wording. The fallback interpolates row.decision, which
// arrives from the Open Collective API and can also be typed by hand into the data table,
// so it is escaped: & first, then < and >, so Slack reads it as text and not as a control
// sequence.
const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

return $input.all()
  .filter((item) => item.json.slack_thread_ts && item.json.slack_channel_id)
  .map((item) => {
    const row = item.json;
    const label = LABELS[row.decision] || `Decision recorded: ${escapeSlack(row.decision)}`;
    return { json: {
      slug: row.slug,
      channel: row.slack_channel_id,
      thread_ts: row.slack_thread_ts,
      reaction: row.decision === 'approved' ? 'white_check_mark' : 'x',
      text: label,
    } };
  });

// The Slack post above runs with onError continueRegularOutput, so a Slack outage never
// holds up an application. A failed post arrives here as { error: ... } with no
// message.ts, and writing that would store an anchor pointing at nothing. Drop those
// items: the row keeps null identifiers, and every later stage already skips a row that
// has none.
const rendered = $('Render application parent message').all();
return $input.all()
  .map((item, index) => ({ item, slug: rendered[index] ? rendered[index].json.slug : null }))
  .filter(({ item, slug }) => Boolean(slug) && Boolean(item.json && item.json.message && item.json.message.ts))
  .map(({ item, slug }) => ({ json: {
    slug,
    channel: item.json.channel,
    thread_ts: item.json.message.ts,
  } }));

// Fed by the data table update, which returns the row it wrote, so the thread anchor is
// read straight off the row. Rows whose parent message never got posted are skipped
// rather than posted loose in the channel: a reply with no thread_ts lands with no
// context.
//
// The host slug comes from the Open Collective API, so it is data, not markup: a value
// containing <!channel>, or a masked link like
// <https://evil.example|opencollective.com/theirs>, would otherwise be honoured by Slack
// in the reviewers' channel. Escape the three characters Slack treats as control
// characters, & first so the other two are not escaped twice. The fixed wording keeps its
// *bold* and its emoji, and org resolves from our own host list.
const ORG_NAMES = { OSE: 'Open Source Europe' };

const escapeSlack = (value) => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

// The host the applicant went to is not a column, so it cannot come off the row. Pair it
// back from the branch that found it, by slug rather than by position: the data table
// update writes one row per input item, but a filtered-out row would shift every index.
const hostBySlug = {};
for (const item of $('Extract decision').all()) {
  hostBySlug[item.json.slug] = item.json.other_host || '';
}

return $input.all()
  .filter((item) => item.json.slack_thread_ts && item.json.slack_channel_id)
  .map((item) => {
    const row = item.json;
    const org = ORG_NAMES[row.org] || row.org;
    const host = hostBySlug[row.slug];
    const where = host
      ? ' The collective is now with the `' + escapeSlack(host) + '` host on Open Collective.'
      : '';
    return { json: {
      slug: row.slug,
      channel: row.slack_channel_id,
      thread_ts: row.slack_thread_ts,
      text: ':large_yellow_circle: *No longer applying to ' + org + '.*' + where
        + ' It can be neither approved nor rejected here, so the application is closed.'
        + ' No email was sent.',
    } };
  });
